mapper.select:
SELECT id, schedule_id AS scheduleId, term, class_code AS classCode, course_code AS courseCode, course_name AS courseName, teacher_no AS teacherNo, teacher_name AS teacherName, week_no AS weekNo, weekday, period_start AS periodStart, period_end AS periodEnd, session_date AS sessionDate, start_time AS startTime, end_time AS endTime, location, status, created_at AS createdAt, updated_at AS updatedAt FROM class_session WHERE 1=1
AND term = #{term}
AND class_code = #{classCode}
ORDER BY week_no ASC, weekday ASC, period_start ASC
